update_md5_116f4a0ee737c290bf9a6e1f8ec79.content_md5_116f4a0ee737c290bf9a6e1f8ec7:
// Handle regular character input
// Ink normally passes printable keys via `inputChar`, but in some terminals
// (notably on Windows) `inputChar` may be empty while `key.sequence` contains
// the typed character.
const seq = typeof key.sequence === "string" ? key.sequence : "";
const seqIsSingleChar = seq && Array.from(seq).length === 1;
const seqIsPrintable =
  seqIsSingleChar &&
  seq !== "\n" &&
  seq !== "\r" &&
  seq !== "\t" &&
  seq !== "\u001b" &&
  seq !== "\b" &&
  seq !== "\x7f";

const charToInsert = inputChar || (seqIsPrintable ? seq : "");

if (charToInsert && !key.ctrl && !key.meta) {
  const result = insertText(input, cursorPosition, charToInsert);
  const { text: capped, position } = capToMaxLength(
    result.text,
    result.position,
    onTruncated
  );
  setInputState(capped);
  setCursorPositionState(position);
  setOriginalInput(capped);
}
